struct Checkout {
    var subtotal: Decimal
    var zone: Int

    var freeShippingThreshold: Decimal { 50 }

    var qualifiesForFreeShipping: Bool {
        subtotal >= freeShippingThreshold
    }

    var shipping: Decimal {
        if qualifiesForFreeShipping { return 0 }
        return zoneRate
    }

    private var zoneRate: Decimal {
        switch zone {
        case 1: return 2.50
        case 2: return 4.50
        case 3: return 6.50
        case 4: return 8.50
        case 5: return 10.50
        case 6: return 12.50
        case 7: return 14.50
        case 8: return 16.50
        case 9: return 18.50
        case 10: return 20.50
        case 11: return 22.50
        case 12: return 24.50
        case 13: return 26.50
        case 14: return 28.50
        case 15: return 30.50
        default: return 4.95
        }
    }
}
